#include <vector>
#include <list>

class entity;
typedef entity* vm_entity_t;
typedef vector<vm_entity_t> entity_list;
typedef entity_list* vm_entity_list_t;

extern list<vm_entity_list_t> script_entity_lists;

void destroy_script_entity_list(vm_entity_list_t lst)
{
  list<vm_entity_list_t>::iterator i = script_entity_lists.begin();
  while(i != script_entity_lists.end())
  {
    if((*i) == lst)
    {
      delete (*i);
      i = script_entity_lists.erase(i);

      return;
    }

    ++i;
  }
}
